window.MLA_QBANK={"L1-0":{"n":1,"s":"quiz","st":"Check your understanding","q":"A model predicts tomorrow's temperature in °C. What kind of problem is this?","o":["Classification","Regression","Clustering"],"c":1,"x":"The label is a number on a continuous scale, so it is <strong>regression<\/strong>. Classification would predict a category such as \"hot / mild / cold\"."},"L1-1":{"n":1,"s":"quiz","st":"Check your understanding","q":"In a dataset of emails labelled spam / not spam, what is the \"label\"?","o":["The words in the email","The sender's address","Whether the email is spam"],"c":2,"x":"The label is the answer we want to predict. Words and sender are <strong>features<\/strong> — the inputs."},"L1-2":{"n":1,"s":"quiz","st":"Check your understanding","q":"Predictions are 3, 5 and true values are 4, 5. What is the MSE?","o":["0.5","1","2"],"c":0,"x":"Errors are $-1$ and $0$; squared: $1$ and $0$; average $= (1+0)/2 = 0.5$."},"L1-3":{"n":1,"s":"quiz","st":"Check your understanding","q":"You group shoppers by buying habits without any predefined categories. This is…","o":["Supervised learning","Unsupervised learning","Reinforcement learning"],"c":1,"x":"There are no labels — the algorithm discovers the groups itself. That is <strong>unsupervised<\/strong> learning (specifically clustering)."},"L1-4":{"n":1,"s":"quiz","st":"Check your understanding","q":"A model scores 100% on its training data but poorly on new data. This is called…","o":["Underfitting","Regularization","Overfitting"],"c":2,"x":"It memorised the training examples instead of learning the general pattern: <strong>overfitting<\/strong>."},"L2-0":{"n":2,"s":"quiz","st":"Check your understanding","q":"What is $(1, 2, 3)\\cdot(4, 0, -1)$?","o":["-3","1","7"],"c":1,"x":"$1\\cdot4 + 2\\cdot0 + 3\\cdot(-1) = 4 + 0 - 3 = 1$."},"L2-1":{"n":2,"s":"quiz","st":"Check your understanding","q":"What is the length of $(6, 8)$?","o":["14","7","10"],"c":2,"x":"$\\sqrt{36 + 64} = \\sqrt{100} = 10$. (14 is the L1 norm.)"},"L2-2":{"n":2,"s":"quiz","st":"Check your understanding","q":"A dataset has 500 examples and 20 features. What is the shape of $X$?","o":["500 × 20","20 × 500","520 × 1"],"c":0,"x":"Rows = examples, columns = features: $500 \\times 20$."},"L2-3":{"n":2,"s":"quiz","st":"Check your understanding","q":"Two vectors have a dot product of 0. What does that tell you?","o":["They are identical","They are perpendicular","One of them must be zero"],"c":1,"x":"$\\cos 90° = 0$, so non-zero vectors with dot product 0 are at a right angle (orthogonal)."},"L2-4":{"n":2,"s":"quiz","st":"Check your understanding","q":"$A$ is $3\\times4$ and $B$ is $4\\times2$. What is the shape of $AB$?","o":["4 × 4","It's not allowed","3 × 2"],"c":2,"x":"$(3\\times\\mathbf{4})(\\mathbf{4}\\times2)$: inner sizes match, result is outer sizes $3\\times2$."},"L3-0":{"n":3,"s":"quiz","st":"Check your understanding","q":"What is the derivative of $f(x) = 5x^4$?","o":["$5x^3$","$4x^3$","$20x^3$"],"c":2,"x":"Power rule: $5 \\cdot 4x^{3} = 20x^3$."},"L3-1":{"n":3,"s":"quiz","st":"Check your understanding","q":"At some $w$, $\\frac{dL}{dw} = -3$. To reduce the loss you should…","o":["increase $w$","decrease $w$","leave $w$ alone"],"c":0,"x":"A negative derivative means the loss goes down as $w$ goes up. Gradient descent does $w - \\eta(-3) = w + 3\\eta$: it increases $w$."},"L3-2":{"n":3,"s":"quiz","st":"Check your understanding","q":"Using the chain rule, what is $\\frac{d}{dx}(2x - 5)^2$?","o":["$2(2x-5)$","$4(2x-5)$","$(2x-5)$"],"c":1,"x":"Outer derivative $2(2x-5)$ times inner derivative $2$: $4(2x-5)$."},"L3-3":{"n":3,"s":"quiz","st":"Check your understanding","q":"For $f(w,b) = 3w + wb$, what is $\\frac{\\partial f}{\\partial w}$?","o":["$3 + w$","$3 + b$","$w + b$"],"c":1,"x":"Treat $b$ as a constant: $\\frac{\\partial}{\\partial w}(3w) = 3$ and $\\frac{\\partial}{\\partial w}(wb) = b$."},"L3-4":{"n":3,"s":"quiz","st":"Check your understanding","q":"The gradient of the loss points…","o":["towards the minimum","sideways along a contour","in the direction of steepest increase"],"c":2,"x":"It points uphill. That's why gradient descent subtracts it."},"L4-0":{"n":4,"s":"quiz","st":"Check your understanding","q":"You flip a fair coin 3 times. What is the probability of 3 heads?","o":["1/3","1/8","1/2"],"c":1,"x":"Independent flips multiply: $0.5^3 = 1/8$."},"L4-1":{"n":4,"s":"quiz","st":"Check your understanding","q":"Data: 2, 4, 6. What is the variance (dividing by $n$)?","o":["8/3 ≈ 2.67","4","2"],"c":0,"x":"Mean is 4. Squared distances: 4, 0, 4. Average: $8/3 \\approx 2.67$."},"L4-2":{"n":4,"s":"quiz","st":"Check your understanding","q":"In Bayes' theorem, $P(A)$ is called the…","o":["posterior","likelihood","prior"],"c":2,"x":"The prior is your belief before seeing the evidence. The posterior $P(A\\mid B)$ is after."},"L4-3":{"n":4,"s":"quiz","st":"Check your understanding","q":"A value has z-score −2. What does that mean?","o":["It is 2 units below the mean","It is 2 standard deviations below the mean","It is an error in the data"],"c":1,"x":"$z = (x - \\mu)/\\sigma = -2$ means $x$ is two standard deviations below the mean."},"L4-4":{"n":4,"s":"quiz","st":"Check your understanding","q":"A normal distribution has $\\mu = 50$, $\\sigma = 5$. Roughly what fraction of values fall between 45 and 55?","o":["68%","95%","99.7%"],"c":0,"x":"45–55 is within 1 standard deviation of the mean: about 68%."},"L5-0":{"n":5,"s":"quiz","st":"Check your understanding","q":"Training error 0.01, test error 2.5. What's happening?","o":["Underfitting","A good fit","Overfitting"],"c":2,"x":"A huge gap between low training error and high test error means the model memorised the training data: <strong>overfitting<\/strong>."},"L5-1":{"n":5,"s":"quiz","st":"Check your understanding","q":"Training error 3.1, test error 3.3, and a simple model. What's the likely problem?","o":["Underfitting","Overfitting","Data leakage"],"c":0,"x":"Both errors are high and similar: the model is too simple to capture the pattern — <strong>underfitting<\/strong>. Try a more flexible model or better features."},"L5-2":{"n":5,"s":"quiz","st":"Check your understanding","q":"Which set should you use to choose between 10 candidate models?","o":["The test set","The validation set (or cross-validation)","The training set"],"c":1,"x":"Choices are made on validation data. The test set is reserved for one final, unbiased evaluation; the training score is too optimistic."},"L5-3":{"n":5,"s":"quiz","st":"Check your understanding","q":"In 5-fold cross-validation, how many models are trained?","o":["1","4","5"],"c":2,"x":"One per fold: each of the 5 folds takes a turn as the validation set."},"L5-4":{"n":5,"s":"quiz","st":"Check your understanding","q":"You standardise all your data using its overall mean, then split into train and test. What's wrong?","o":["Data leakage: test data influenced the preprocessing","Nothing — that's the correct order","Overfitting caused by too many features"],"c":0,"x":"The mean was computed partly from test data. Split first, compute statistics on the training set only, then apply them to the test set."},"L6-0":{"n":6,"s":"quiz","st":"Check your understanding","q":"A model is $\\hat{y} = 3x - 2$. What does it predict for $x = 4$?","o":["12","10","14"],"c":1,"x":"$3 \\times 4 - 2 = 10$."},"L6-1":{"n":6,"s":"quiz","st":"Check your understanding","q":"The least-squares line always passes through which point?","o":["$(\\bar{x}, \\bar{y})$, the mean of the data","The origin $(0,0)$","The first data point"],"c":0,"x":"From $\\partial L/\\partial b = 0$ we got $b = \\bar{y} - w\\bar{x}$, i.e. $\\bar{y} = w\\bar{x} + b$: the line goes through the mean point."},"L6-2":{"n":6,"s":"quiz","st":"Check your understanding","q":"A model's $R^2$ on test data is 0. What does that mean?","o":["It's perfect","It predicts the opposite of the truth","It's no better than always predicting the average"],"c":2,"x":"$R^2 = 0$ means $\\text{SS}_{\\text{res}} = \\text{SS}_{\\text{tot}}$: the same error as the mean-only baseline."},"L6-3":{"n":6,"s":"quiz","st":"Check your understanding","q":"For data with $\\sum(x_i-\\bar{x})(y_i-\\bar{y}) = 12$ and $\\sum(x_i-\\bar{x})^2 = 4$, what is the slope?","o":["0.33","3","48"],"c":1,"x":"$w = 12 / 4 = 3$."},"L6-4":{"n":6,"s":"quiz","st":"Check your understanding","q":"Why might you prefer gradient descent over the normal equation?","o":["With very many features, inverting $X^\\top X$ is too slow","Gradient descent always gives a more accurate answer","The normal equation only works for one feature"],"c":0,"x":"The normal equation works for any number of features, but its cost grows roughly like $d^3$. Gradient descent scales to huge problems (Lesson 7)."},"L7-0":{"n":7,"s":"quiz","st":"Check your understanding","q":"Current $w = 2$, gradient $\\partial L/\\partial w = 4$, learning rate $0.1$. What is the new $w$?","o":["2.4","1.6","-2"],"c":1,"x":"$w - \\eta\\cdot\\text{grad} = 2 - 0.1\\times4 = 1.6$."},"L7-1":{"n":7,"s":"quiz","st":"Check your understanding","q":"Your loss gets bigger every step and eventually becomes \"nan\". The most likely cause?","o":["Learning rate too small","Too much training data","Learning rate too large"],"c":2,"x":"Steps overshoot the minimum by more each time — divergence. Reduce the learning rate (and check feature scaling)."},"L7-2":{"n":7,"s":"quiz","st":"Check your understanding","q":"Which variant uses a single random example per update?","o":["Stochastic gradient descent","Batch gradient descent","The normal equation"],"c":0,"x":"SGD uses one example at a time; batch uses all; mini-batch uses a small group."},"L7-3":{"n":7,"s":"quiz","st":"Check your understanding","q":"Why does standardising features usually speed up gradient descent?","o":["It reduces the number of parameters","It makes the loss landscape rounder, so the gradient points more directly at the minimum","It removes the need for a learning rate"],"c":1,"x":"Different feature scales create long narrow valleys that make descent zigzag. Similar scales give a rounder bowl."},"L7-4":{"n":7,"s":"quiz","st":"Check your understanding","q":"All predictions are too high. What sign does $\\partial L/\\partial b$ have, and what happens to $b$?","o":["Negative; $b$ increases","Zero; $b$ stays the same","Positive; $b$ decreases"],"c":2,"x":"$\\frac{\\partial L}{\\partial b} = \\frac{2}{n}\\sum(\\hat{y}_i - y_i) &gt; 0$ when predictions are too high, so $b \\leftarrow b - \\eta(\\text{positive})$ decreases — lowering every prediction."},"L8-0":{"n":8,"s":"quiz","st":"Check your understanding","q":"What is $\\sigma(0)$?","o":["0","0.5","1"],"c":1,"x":"$\\sigma(0) = 1/(1 + e^0) = 1/2$."},"L8-1":{"n":8,"s":"quiz","st":"Check your understanding","q":"A model has $z = 2x - 6$. Where is the decision boundary (threshold 0.5)?","o":["$x = 6$","$x = 0.5$","$x = 3$"],"c":2,"x":"The boundary is where $z = 0$: $2x - 6 = 0 \\Rightarrow x = 3$."},"L8-2":{"n":8,"s":"quiz","st":"Check your understanding","q":"The true label is 1. Which prediction gives the largest log loss?","o":["$p = 0.05$","$p = 0.5$","$p = 0.95$"],"c":0,"x":"$-\\ln 0.05 \\approx 3.0$, much larger than $-\\ln 0.5 \\approx 0.69$ or $-\\ln 0.95 \\approx 0.05$. Confident and wrong is punished most."},"L8-3":{"n":8,"s":"quiz","st":"Check your understanding","q":"A feature has weight $w = \\ln 2 \\approx 0.693$. Increasing that feature by 1…","o":["adds 0.693 to the probability","doubles the odds","doubles the probability"],"c":1,"x":"The odds are multiplied by $e^{w} = e^{\\ln 2} = 2$. The probability itself changes by a varying amount."},"L8-4":{"n":8,"s":"quiz","st":"Check your understanding","q":"For one example, $p = 0.8$, $y = 0$, $x = 3$. What is $\\partial\\ell/\\partial w$?","o":["-0.6","0.8","2.4"],"c":2,"x":"$(p - y)\\,x = (0.8 - 0)\\times3 = 2.4$. Positive, so gradient descent decreases $w$, lowering $p$ for this example."},"L9-0":{"n":9,"s":"quiz","st":"Check your understanding","q":"TP = 30, FP = 10, FN = 20. What is the precision?","o":["0.60","0.75","0.50"],"c":1,"x":"Precision $= 30/(30 + 10) = 0.75$. (Recall would be $30/(30+20) = 0.60$.)"},"L9-1":{"n":9,"s":"quiz","st":"Check your understanding","q":"A fraud detector must miss as few frauds as possible. Which metric matters most?","o":["Precision","Specificity","Recall"],"c":2,"x":"Missing a fraud is a false negative; recall $= TP/(TP+FN)$ measures how many frauds are caught."},"L9-2":{"n":9,"s":"quiz","st":"Check your understanding","q":"You lower the classification threshold from 0.5 to 0.3. What usually happens?","o":["Recall goes up, precision goes down","Precision goes up, recall goes down","Both go up"],"c":0,"x":"More examples get flagged positive: more true positives are caught (recall ↑) but more false alarms too (precision ↓)."},"L9-3":{"n":9,"s":"quiz","st":"Check your understanding","q":"A model has ROC-AUC = 0.5. What does that suggest?","o":["It's perfect","It ranks no better than random","It's right half of the time on each class"],"c":1,"x":"AUC 0.5 means a random positive is scored above a random negative only half the time — like a coin flip."},"L9-4":{"n":9,"s":"quiz","st":"Check your understanding","q":"Errors are 1, −1, 1, −5. Which is larger, MAE or RMSE?","o":["MAE","They are equal","RMSE"],"c":2,"x":"MAE $= 8/4 = 2$. MSE $= (1+1+1+25)/4 = 7$, RMSE $\\approx 2.65$. Squaring makes the big error count more."},"L10-0":{"n":10,"s":"quiz","st":"Check your understanding","q":"Your model's training and test errors are both high and close together. What should you try?","o":["A more flexible model or less regularization","Stronger regularization","Removing features"],"c":0,"x":"Both errors high and similar = high bias (underfitting). Make the model more flexible; more regularization would make it worse."},"L10-1":{"n":10,"s":"quiz","st":"Check your understanding","q":"What happens as $\\lambda \\to \\infty$ in ridge regression?","o":["The weights grow without limit","Nothing changes","All weights approach 0, so the model predicts a constant"],"c":2,"x":"An enormous penalty forces every weight towards zero; only the (unpenalised) bias remains, so predictions are roughly the mean of $y$."},"L10-2":{"n":10,"s":"quiz","st":"Check your understanding","q":"You have 500 features but suspect only about 10 matter. Which regularization fits best?","o":["Ridge (L2)","Lasso (L1)","No regularization"],"c":1,"x":"Lasso sets unhelpful weights exactly to zero, keeping a small set of useful features."},"L10-3":{"n":10,"s":"quiz","st":"Check your understanding","q":"One feature, no intercept: $\\sum x_iy_i = 20$, $\\sum x_i^2 = 8$. What is the ridge weight with $\\lambda = 2$?","o":["2.5","2.0","10"],"c":1,"x":"$w = 20/(8 + 2) = 2$. Without regularization it would be $20/8 = 2.5$."},"L10-4":{"n":10,"s":"quiz","st":"Check your understanding","q":"In scikit-learn's <code>LogisticRegression<\/code>, you change <code>C<\/code> from 1 to 0.01. Regularization becomes…","o":["much stronger","much weaker","switched off"],"c":0,"x":"$C = 1/\\lambda$, so a smaller $C$ means a larger $\\lambda$ — stronger regularization."},"L11-0":{"n":11,"s":"quiz","st":"Check your understanding","q":"What is the Euclidean distance between $(1, 2)$ and $(4, 6)$?","o":["7","5","25"],"c":1,"x":"$\\sqrt{3^2 + 4^2} = \\sqrt{25} = 5$. (7 is the Manhattan distance.)"},"L11-1":{"n":11,"s":"quiz","st":"Check your understanding","q":"With $k = 1$, what is kNN's accuracy on its own training data (no duplicate points)?","o":["100%","Around 50%","It depends on the data"],"c":0,"x":"Each training point's nearest neighbour is itself, so it's always \"correct\" — which says nothing about generalization."},"L11-2":{"n":11,"s":"quiz","st":"Check your understanding","q":"Your kNN boundary is jagged with many small islands. What should you change?","o":["Decrease $k$","Remove feature scaling","Increase $k$"],"c":2,"x":"Jagged boundaries mean high variance. Averaging over more neighbours smooths the boundary."},"L11-3":{"n":11,"s":"quiz","st":"Check your understanding","q":"The 3 nearest neighbours of a house sold for 200k, 260k and 230k. What does kNN regression ($k = 3$, unweighted) predict?","o":["260k","230k","200k"],"c":1,"x":"The average: $(200 + 260 + 230)/3 = 230$k."},"L11-4":{"n":11,"s":"quiz","st":"Check your understanding","q":"Why does kNN struggle with hundreds of features?","o":["In high dimensions all points are roughly equally far apart, so \"nearest\" loses meaning","It can only use two features","The vote always ties"],"c":0,"x":"The curse of dimensionality: neighbourhoods must stretch across most of the space, so neighbours aren't really similar."},"L12-0":{"n":12,"s":"quiz","st":"Check your understanding","q":"What does the \"naive\" assumption say?","o":["All classes are equally likely","Features follow a normal distribution","Features are independent of each other given the class"],"c":2,"x":"Conditional independence lets us multiply individual feature probabilities instead of modelling every combination."},"L12-1":{"n":12,"s":"quiz","st":"Check your understanding","q":"Why is Laplace smoothing needed?","o":["To make training faster","So a word never seen in a class doesn't make that class's probability exactly zero","To remove common words"],"c":1,"x":"Without smoothing, one zero factor in the product wipes out all the other evidence."},"L12-2":{"n":12,"s":"quiz","st":"Check your understanding","q":"A class has 20 words in total, the vocabulary has 30 words, and \"deal\" appears 4 times in the class. With add-one smoothing, $P(\\text{deal} \\mid \\text{class})$ is…","o":["5/50 = 0.1","4/20 = 0.2","5/20 = 0.25"],"c":0,"x":"$(4 + 1)/(20 + 30) = 5/50 = 0.1$."},"L12-3":{"n":12,"s":"quiz","st":"Check your understanding","q":"Why do implementations add log-probabilities instead of multiplying probabilities?","o":["Logs are more accurate in theory","It changes which class wins","Multiplying many small numbers underflows to zero"],"c":2,"x":"Products of hundreds of small probabilities become too small to store. Logs turn them into sums of manageable numbers, without changing the ranking."},"L12-4":{"n":12,"s":"quiz","st":"Check your understanding","q":"Which variant suits features like height and weight?","o":["Multinomial NB","Gaussian NB","Bernoulli NB"],"c":1,"x":"Continuous measurements are modelled with a normal (Gaussian) distribution per class."},"L13-0":{"n":13,"s":"quiz","st":"Check your understanding","q":"A node has 5 examples of class A and 5 of class B. What is its Gini impurity?","o":["0","0.5","1"],"c":1,"x":"$1 - (0.5^2 + 0.5^2) = 1 - 0.5 = 0.5$ — the maximum for two classes."},"L13-1":{"n":13,"s":"quiz","st":"Check your understanding","q":"Which split is better: one that creates two pure children, or one whose children have the same class mix as the parent?","o":["Two pure children","Same mix as the parent","They're equally good"],"c":0,"x":"Pure children have impurity 0 — the maximum possible gain. Keeping the parent's mix gives zero gain."},"L13-2":{"n":13,"s":"quiz","st":"Check your understanding","q":"Why don't decision trees need feature scaling?","o":["They standardise features internally","They only work with categorical features","Each split compares one feature with a threshold, so the feature's units don't matter"],"c":2,"x":"Rescaling a feature just rescales its thresholds; the same examples go left and right."},"L13-3":{"n":13,"s":"quiz","st":"Check your understanding","q":"A tree has 100% training accuracy and 85% test accuracy. What would most likely help?","o":["Allow deeper trees","Limit max_depth or increase min_samples_leaf","Use entropy instead of Gini"],"c":1,"x":"That gap is overfitting; restricting the tree's growth reduces variance."},"L13-4":{"n":13,"s":"quiz","st":"Check your understanding","q":"What shape are a decision tree's decision boundaries?","o":["Axis-parallel staircases (boxes)","Single straight diagonal lines","Smooth curves"],"c":0,"x":"Each split is \"one feature ≤ threshold\", a cut parallel to an axis. Together they make rectangles."},"L14-0":{"n":14,"s":"quiz","st":"Check your understanding","q":"Why does a majority vote of many classifiers help?","o":["Each model sees more data","It always reaches 100% accuracy","Independent errors tend to cancel out when combined"],"c":2,"x":"If models err on different examples, the majority is usually right even when individuals are wrong."},"L14-1":{"n":14,"s":"quiz","st":"Check your understanding","q":"What fraction of distinct examples does a bootstrap sample contain, roughly?","o":["63%","50%","100%"],"c":0,"x":"$1 - (1 - 1/n)^n \\approx 1 - e^{-1} \\approx 0.632$."},"L14-2":{"n":14,"s":"quiz","st":"Check your understanding","q":"What does a random forest add on top of bagging?","o":["Sequential training","A random subset of features considered at each split","Example weights"],"c":1,"x":"Feature subsampling decorrelates the trees, making the average stronger."},"L14-3":{"n":14,"s":"quiz","st":"Check your understanding","q":"In gradient boosting with squared error, each new tree is trained to predict…","o":["the original labels $y$","random noise","the residuals $y - F(x)$ of the current ensemble"],"c":2,"x":"The residual is the negative gradient of the squared loss; fitting it is a gradient descent step in prediction space."},"L14-4":{"n":14,"s":"quiz","st":"Check your understanding","q":"A weak learner has weighted error $\\varepsilon = 0.5$. What is its AdaBoost vote $\\alpha$?","o":["0","0.5","1"],"c":0,"x":"$\\alpha = \\frac12\\ln\\frac{0.5}{0.5} = \\frac12\\ln 1 = 0$. A coin-flip learner gets no say."},"L15-0":{"n":15,"s":"quiz","st":"Check your understanding","q":"An SVM has $\\|\\mathbf{w}\\| = 4$. How wide is its margin?","o":["4","0.5","8"],"c":1,"x":"Margin $= 2/\\|\\mathbf{w}\\| = 2/4 = 0.5$."},"L15-1":{"n":15,"s":"quiz","st":"Check your understanding","q":"A point with $y = -1$ has score $\\mathbf{w}\\cdot\\mathbf{x} + b = 0.5$. What is its hinge loss?","o":["1.5","0.5","0"],"c":0,"x":"$\\max(0, 1 - y\\cdot\\text{score}) = \\max(0, 1 - (-1)(0.5)) = 1.5$. It's on the wrong side."},"L15-2":{"n":15,"s":"quiz","st":"Check your understanding","q":"You delete a training point that is far from the boundary and outside the margin. What happens to the SVM?","o":["The boundary moves towards it","The margin doubles","Nothing — it isn't a support vector"],"c":2,"x":"Only support vectors define the solution; points with zero hinge loss don't affect it."},"L15-3":{"n":15,"s":"quiz","st":"Check your understanding","q":"Your RBF SVM gets 100% training accuracy and 70% test accuracy. What should you try?","o":["Increase $\\gamma$ and $C$","Decrease $\\gamma$ and/or $C$","Switch off feature scaling"],"c":1,"x":"That's overfitting. Smaller $\\gamma$ smooths the boundary; smaller $C$ allows more margin violations — both regularize."},"L15-4":{"n":15,"s":"quiz","st":"Check your understanding","q":"What does a kernel function compute?","o":["A dot product in a transformed feature space, without building that space","The distance between two classes","The number of support vectors"],"c":0,"x":"$K(\\mathbf{x}, \\mathbf{z}) = \\phi(\\mathbf{x})\\cdot\\phi(\\mathbf{z})$, computed directly from $\\mathbf{x}$ and $\\mathbf{z}$."},"L16-0":{"n":16,"s":"quiz","st":"Check your understanding","q":"In k-means, after assigning points, each centroid is moved to…","o":["the point farthest from it","the mean of the points assigned to it","a random new location"],"c":1,"x":"The update step sets each centroid to the average of its cluster, which minimises that cluster's sum of squared distances."},"L16-1":{"n":16,"s":"quiz","st":"Check your understanding","q":"Why can't you choose $k$ by minimising inertia?","o":["Inertia can't be computed without labels","Inertia increases with $k$","Inertia always decreases as $k$ grows, reaching 0 when every point is its own cluster"],"c":2,"x":"More clusters always fit at least as tightly, so inertia alone favours too many clusters. Look for the elbow or use silhouette."},"L16-2":{"n":16,"s":"quiz","st":"Check your understanding","q":"A point has $a = 2$ and $b = 6$. What is its silhouette value?","o":["0.67","0.33","3"],"c":0,"x":"$(6 - 2)/\\max(2, 6) = 4/6 \\approx 0.67$."},"L16-3":{"n":16,"s":"quiz","st":"Check your understanding","q":"Your data has two interlocking crescent shapes and a few outliers. Which method fits best?","o":["k-means with $k = 2$","DBSCAN","k-means with $k = 10$"],"c":1,"x":"DBSCAN follows dense regions of any shape and labels outliers as noise."},"L16-4":{"n":16,"s":"quiz","st":"Check your understanding","q":"In DBSCAN, what is a core point?","o":["The centre of a cluster","A point labelled as noise","A point with at least <code>min_samples<\/code> points within distance $\\varepsilon$"],"c":2,"x":"Core points sit in dense regions; clusters grow outwards from them."},"L17-0":{"n":17,"s":"quiz","st":"Check your understanding","q":"What is the first principal component?","o":["The feature with the largest values","The direction along which the data varies the most","The average of all features"],"c":1,"x":"PC1 is the direction of maximum variance — the eigenvector of the covariance matrix with the largest eigenvalue."},"L17-1":{"n":17,"s":"quiz","st":"Check your understanding","q":"Eigenvalues are 6, 3 and 1. What fraction of the variance do the first two components explain?","o":["60%","70%","90%"],"c":2,"x":"$(6 + 3)/(6 + 3 + 1) = 9/10 = 90\\%$."},"L17-2":{"n":17,"s":"quiz","st":"Check your understanding","q":"Why standardise features before PCA?","o":["Otherwise features with large units dominate the variance, and so the components","PCA only accepts values between 0 and 1","It removes the need for eigenvectors"],"c":0,"x":"PCA maximises variance; a feature in millimetres has far more raw variance than the same feature in metres."},"L17-3":{"n":17,"s":"quiz","st":"Check your understanding","q":"$\\Sigma\\mathbf{v} = 3\\mathbf{v}$. What is $\\mathbf{v}$ and what is 3?","o":["$\\mathbf{v}$ is an eigenvalue, 3 is an eigenvector","$\\mathbf{v}$ is an eigenvector, 3 is its eigenvalue","$\\mathbf{v}$ is the mean, 3 is the variance"],"c":1,"x":"The matrix only stretches $\\mathbf{v}$ by the factor 3, so $\\mathbf{v}$ is an eigenvector with eigenvalue 3."},"L17-4":{"n":17,"s":"quiz","st":"Check your understanding","q":"A t-SNE plot shows one big cluster and one small one. What can you conclude about their real sizes?","o":["The big one has more spread in the original space","The big one has more points","Nothing reliable — cluster sizes in t-SNE plots don't carry meaning"],"c":2,"x":"t-SNE expands dense clusters and contracts sparse ones, so visual sizes aren't trustworthy."},"L18-0":{"n":18,"s":"quiz","st":"Check your understanding","q":"Why can't a single neuron learn XOR?","o":["XOR needs more than two inputs","A single neuron draws one straight boundary, and XOR's classes aren't linearly separable","Sigmoid can't output 0"],"c":1,"x":"The 1s and 0s lie on opposite diagonals; separating them needs at least two lines combined, i.e. a hidden layer."},"L18-1":{"n":18,"s":"quiz","st":"Check your understanding","q":"What happens if you remove all activation functions from a deep network?","o":["It becomes equivalent to a single linear model","It trains faster and is more accurate","It can only output 0 or 1"],"c":0,"x":"A chain of linear maps is still linear: $V(W\\mathbf{x}) = (VW)\\mathbf{x}$."},"L18-2":{"n":18,"s":"quiz","st":"Check your understanding","q":"What is ReLU(−3)?","o":["−3","3","0"],"c":2,"x":"$\\max(0, -3) = 0$."},"L18-3":{"n":18,"s":"quiz","st":"Check your understanding","q":"Output $p = 0.8$, label $y = 0$, hidden activation $h_1 = 0.5$. What is $\\partial L/\\partial v_1$ (sigmoid + log loss)?","o":["−0.4","0.4","0.8"],"c":1,"x":"$\\delta_{\\text{out}} = p - y = 0.8$; $\\partial L/\\partial v_1 = 0.8\\times0.5 = 0.4$. Positive, so $v_1$ will decrease."},"L18-4":{"n":18,"s":"quiz","st":"Check your understanding","q":"Why must weights be initialised randomly rather than all zeros?","o":["Identical weights give identical neurons with identical gradients, so they never learn different features","Zero weights cause division by zero","Random weights guarantee the global minimum"],"c":0,"x":"Random initialisation \"breaks the symmetry\" so each hidden neuron can specialise."},"L19-0":{"n":19,"s":"quiz","st":"Check your understanding","q":"A 32×32 input, 5×5 kernel, padding 0, stride 1. What is the output width?","o":["32","28","27"],"c":1,"x":"$(32 - 5 + 0)/1 + 1 = 28$."},"L19-1":{"n":19,"s":"quiz","st":"Check your understanding","q":"Why do CNNs need far fewer parameters than fully connected networks on images?","o":["They ignore colour","They use smaller images","Each small kernel is shared across all positions in the image"],"c":2,"x":"Weight sharing: one 3×3 kernel's few weights are reused at every location."},"L19-2":{"n":19,"s":"quiz","st":"Check your understanding","q":"What problem do LSTMs solve compared with plain RNNs?","o":["Gradients vanishing over long sequences, so the network can't remember far back","RNNs can't process text","RNNs need labelled data"],"c":0,"x":"The gated cell state lets information and gradients flow across many time steps."},"L19-3":{"n":19,"s":"quiz","st":"Check your understanding","q":"In self-attention, how is the similarity between a query and a key measured?","o":["Euclidean distance","A (scaled) dot product","A decision tree"],"c":1,"x":"Scores are $\\mathbf{q}\\cdot\\mathbf{k}/\\sqrt{d_k}$, then softmax turns them into weights."},"L19-4":{"n":19,"s":"quiz","st":"Check your understanding","q":"2×2 max pooling on $\\begin{bmatrix}1&5\\\\3&2\\end{bmatrix}$ gives…","o":["2.75","1","5"],"c":2,"x":"Max pooling keeps the largest value in the window: 5."},"L20-0":{"n":20,"s":"quiz","st":"Check your understanding","q":"Why not encode cities as Chennai = 1, Mumbai = 2, Delhi = 3 for a linear model?","o":["Numbers are slower than text","The model would treat the codes as ordered quantities, e.g. Delhi = 3 × Chennai","Linear models can't use integers"],"c":1,"x":"Arbitrary numbers impose a fake order and spacing. One-hot encoding treats categories as equally different."},"L20-1":{"n":20,"s":"quiz","st":"Check your understanding","q":"Where should the median used to fill missing values come from?","o":["The whole dataset","The test set","The training set only"],"c":2,"x":"Like all learned preprocessing statistics, it must come from training data to avoid leakage."},"L20-2":{"n":20,"s":"quiz","st":"Check your understanding","q":"A column holds account balances from 0 to 5,000,000, mostly under 10,000. A sensible transformation is…","o":["A log transform, e.g. <code>np.log1p<\/code>","One-hot encoding","Deleting the column"],"c":0,"x":"The log compresses the huge range so a few extreme values don't dominate. <code>log1p<\/code> also handles zeros."},"L20-3":{"n":20,"s":"quiz","st":"Check your understanding","q":"What is the main advantage of putting preprocessing inside a Pipeline?","o":["It makes models more accurate in every case","Preprocessing is re-fitted on training data inside each CV fold and travels with the model into production","It removes the need for a test set"],"c":1,"x":"Pipelines prevent leakage and guarantee identical processing in training and deployment."},"L20-4":{"n":20,"s":"quiz","st":"Check your understanding","q":"Your new model scores ROC-AUC 0.52 and the baseline scores 0.50. What does that tell you?","o":["The model is excellent","The baseline is broken","The model has learned almost nothing beyond guessing — revisit features and data"],"c":2,"x":"Always compare with a baseline; a tiny improvement over random ranking means little useful signal has been captured."},"L21-0":{"n":21,"s":"quiz","st":"Check your understanding","q":"A model never receives applicants' ethnicity. Can it still discriminate by ethnicity?","o":["No — it can't use information it doesn't have","Yes — other features can act as proxies for ethnicity","Only if it is a neural network"],"c":1,"x":"Features like postcode or school are often correlated with protected attributes, so a model can reproduce group differences without the attribute itself."},"L21-1":{"n":21,"s":"quiz","st":"Check your understanding","q":"Group A's selection rate is 0.50 and group B's is 0.30. What is the demographic-parity ratio, and does it pass the four-fifths rule of thumb?","o":["0.6 — it does not pass","0.6 — it passes","0.2 — it passes"],"c":0,"x":"$0.30/0.50 = 0.6$, which is below 0.8, so it would be flagged for possible adverse impact."},"L21-2":{"n":21,"s":"quiz","st":"Check your understanding","q":"\"Equal opportunity\" asks which rate to be the same for every group?","o":["The selection rate","The precision","The true-positive rate"],"c":2,"x":"Equal opportunity (Hardt, Price &amp; Srebro, 2016) requires that qualified people — the true positives — are approved at the same rate in every group."},"L21-3":{"n":21,"s":"quiz","st":"Check your understanding","q":"Two groups have different base rates. A model has equal precision and equal TPR for both. What must be true?","o":["Their false-positive rates are also equal","Their false-positive rates differ (unless the model is perfect)","Their accuracies are equal"],"c":1,"x":"By the identity $\\text{FPR} = \\frac{p}{1-p}\\cdot\\frac{1-\\text{PPV}}{\\text{PPV}}\\cdot\\text{TPR}$, different base rates $p$ force different FPRs."},"L21-4":{"n":21,"s":"quiz","st":"Check your understanding","q":"A hospital model predicts healthcare <em>spending<\/em> to decide who gets extra care. What kind of bias is the biggest risk?","o":["Label (measurement) bias — spending is a proxy for need","Too little regularisation","The learning rate is too high"],"c":0,"x":"This is the Obermeyer et al. (2019) case: groups with less access to care spend less at the same level of need, so the label understates their need."},"L22-0":{"n":22,"s":"quiz","st":"Check your understanding","q":"Which clause filters <em>groups<\/em> after aggregation?","o":["WHERE","HAVING","ORDER BY"],"c":1,"x":"<code>WHERE<\/code> filters rows before grouping; <code>HAVING<\/code> filters the grouped results, for example <code>HAVING COUNT(*) &gt;= 3<\/code>."},"L22-1":{"n":22,"s":"quiz","st":"Check your understanding","q":"12 customers, 7 of whom placed orders. How many rows does <code>customers LEFT JOIN orders<\/code> followed by <code>GROUP BY customer<\/code> give?","o":["12","7","As many as there are orders"],"c":0,"x":"The left join keeps every customer (those without orders get NULLs), and grouping gives one row per customer: 12."},"L22-2":{"n":22,"s":"quiz","st":"Check your understanding","q":"You join houses to viewings (one row per viewing) and then take <code>AVG(price)<\/code>. What goes wrong?","o":["Nothing","Houses without viewings count twice","Houses with many viewings count many times"],"c":2,"x":"Each house appears once per matching viewing, so its price is repeated. Aggregate viewings first, then join."},"L22-3":{"n":22,"s":"quiz","st":"Check your understanding","q":"Which window-function expression gives each house's price minus its area's average price?","o":["<code>price - AVG(price)<\/code> with <code>GROUP BY area<\/code>","<code>price - AVG(price) OVER (PARTITION BY area)<\/code>","<code>RANK() OVER (ORDER BY price)<\/code>"],"c":1,"x":"The window version computes the area average for every row without collapsing the rows."},"L22-4":{"n":22,"s":"quiz","st":"Check your understanding","q":"A churn model uses \"number of support calls\" counted over the customer's whole history, including after the prediction date. What's the problem?","o":["Leakage: the feature uses future information","The feature is categorical","The join is too slow"],"c":0,"x":"Features must be computed only from events before each row's cut-off time; otherwise test scores are optimistic."},"L23-0":{"n":23,"s":"quiz","st":"Check your understanding","q":"Which of these is a hyperparameter?","o":["A linear model's weights","The number of neighbours $k$ in kNN","A tree's split thresholds"],"c":1,"x":"$k$ is chosen before training. Weights and split thresholds are parameters learned from the data."},"L23-1":{"n":23,"s":"quiz","st":"Check your understanding","q":"A grid has 3 values for each of 4 hyperparameters and uses 5-fold CV. How many models are trained, not counting the final refit?","o":["60","81","405"],"c":2,"x":"$3^4 = 81$ settings × 5 folds = 405 fits."},"L23-2":{"n":23,"s":"quiz","st":"Check your understanding","q":"Why does random search usually beat grid search with the same budget?","o":["It tries many more distinct values of the hyperparameters that matter","It always finds the global best","It needs no cross-validation"],"c":0,"x":"Usually only a few hyperparameters matter; a grid wastes tries repeating the same few values of them."},"L23-3":{"n":23,"s":"quiz","st":"Check your understanding","q":"A grid search reports a best CV accuracy of 0.95. What is the honest estimate of the tuned model's accuracy?","o":["Exactly 0.95","Usually a bit lower; measure it with nested CV or an untouched test set","Higher than 0.95"],"c":1,"x":"The best of many tries is optimistic; the selection used the same folds that produced the score."},"L23-4":{"n":23,"s":"quiz","st":"Check your understanding","q":"Depths 4 and 6 score 0.929 and 0.935, and the standard error at the best is 0.012. The one-standard-error rule picks…","o":["Depth 4, the simpler model within one SE of the best","Depth 6, the highest score","Neither"],"c":0,"x":"$0.935 - 0.012 = 0.923$, and depth 4's 0.929 is above that, so the simpler tree is preferred."},"L24-0":{"n":24,"s":"quiz","st":"Check your understanding","q":"Permutation importance measures…","o":["How often a feature is used in splits","How much the test score drops when a feature's values are shuffled","A feature's correlation with the target"],"c":1,"x":"Shuffling destroys the feature's information; a big drop means the model relied on it."},"L24-1":{"n":24,"s":"quiz","st":"Check your understanding","q":"A model's baseline prediction is 100 and it predicts 130 for Priya. Her SHAP values must add up to…","o":["30","130","1"],"c":0,"x":"Efficiency: contributions sum to prediction minus baseline."},"L24-2":{"n":24,"s":"quiz","st":"Check your understanding","q":"In $f = 4x_1x_3$, explained at $x_1 = x_3 = 1$ against a baseline of 0, the SHAP value of $x_1$ is…","o":["4","0","2"],"c":2,"x":"The interaction's credit is shared equally between the two features that create it."},"L24-3":{"n":24,"s":"quiz","st":"Check your understanding","q":"A PDP shows predictions rising with \"number of support calls\". Can we conclude that more support calls cause customers to leave?","o":["Yes","No: it shows what the model relies on, not what causes the outcome","Only if the model is accurate"],"c":1,"x":"Unhappy customers call support and also leave; the calls may be a symptom, not a cause."},"L24-4":{"n":24,"s":"quiz","st":"Check your understanding","q":"ICE curves for a feature are parallel lines at different heights. What does that suggest?","o":["The feature has the same effect for everyone, with no interaction with other features","The feature is useless","The model is overfitting"],"c":0,"x":"Parallel curves mean the same shape of effect for each row; crossing or diverging curves reveal interactions."},"L25-0":{"n":25,"s":"quiz","st":"Check your understanding","q":"0.5% of transactions are fraud. A model that never flags fraud has accuracy…","o":["50%","0%","99.5%"],"c":2,"x":"It's right on every non-fraud case: 99.5%. That's why accuracy is the wrong metric here."},"L25-1":{"n":25,"s":"quiz","st":"Check your understanding","q":"Lowering the threshold of a fixed model changes…","o":["Precision and recall, but not average precision","Average precision only","Nothing"],"c":0,"x":"Average precision summarises all thresholds, so it depends only on the ranking of the scores."},"L25-2":{"n":25,"s":"quiz","st":"Check your understanding","q":"When should SMOTE or oversampling be applied?","o":["To the whole dataset before splitting","To the training folds only","To the test set"],"c":1,"x":"Resampling before splitting puts copies (or near-copies) of the same positives on both sides, which leaks."},"L25-3":{"n":25,"s":"quiz","st":"Check your understanding","q":"Why does Isolation Forest give anomalies high scores?","o":["They have large values","Random splits isolate them in very few steps","They are labelled"],"c":1,"x":"Points that are few and different are separated from the rest quickly, so their average path length is short."},"L25-4":{"n":25,"s":"quiz","st":"Check your understanding","q":"With two separate clusters of normal data, which detector is most likely to miss anomalies between the clusters?","o":["Local Outlier Factor","Isolation Forest","A z-score from the overall mean"],"c":2,"x":"Points between the clusters are close to the overall mean, so their z-scores look normal."},"L26-0":{"n":26,"s":"quiz","st":"Check your understanding","q":"For daily sales with a strong weekly pattern, the \"seasonal naive\" forecast for next Saturday is…","o":["Next Friday's actual sales","Last Saturday's sales","The average of all days"],"c":1,"x":"It repeats the value from one season (one week) earlier."},"L26-1":{"n":26,"s":"quiz","st":"Check your understanding","q":"Why is a shuffled k-fold split wrong for forecasting?","o":["It's too slow","It uses too little data","It trains on days after the ones it tests, which leaks the future"],"c":2,"x":"Neighbouring days are similar, so the model \"remembers\" nearby values it won't have in real use."},"L26-2":{"n":26,"s":"quiz","st":"Check your understanding","q":"A model has MASE 1.3. What does that mean?","o":["Its error is 30% worse than the seasonal naive forecast's","It's 30% accurate","It beats the baseline by 30%"],"c":0,"x":"MASE divides by the seasonal naive error; above 1 means worse than the baseline."},"L26-3":{"n":26,"s":"quiz","st":"Check your understanding","q":"Which feature leaks when predicting day $d$?","o":["Sales on day $d - 7$","A 7-day rolling mean that includes day $d$","The day of the week of $d$"],"c":1,"x":"Shift the series before rolling, so the window ends at day $d - 1$."},"L26-4":{"n":26,"s":"quiz","st":"Check your understanding","q":"Sales grow steadily every year. Why might a random forest on the raw sales level forecast poorly?","o":["Forests can't use lags","Forests need scaled features","Trees can't predict values above the range seen in training"],"c":2,"x":"A tree's prediction is an average of training targets, so it can't follow a trend beyond them. Model the change, or detrend."},"L27-0":{"n":27,"s":"quiz","st":"Check your understanding","q":"A user never clicked an item. In implicit feedback, that means…","o":["They dislike it","Either they dislike it or they never saw it","They like it"],"c":1,"x":"Missing interactions mix \"not interested\" with \"not shown\", which is the central difficulty of implicit data."},"L27-1":{"n":27,"s":"quiz","st":"Check your understanding","q":"Why are ratings centred (minus each user's average) before computing similarity?","o":["So a harsh and a generous rater with the same tastes look alike","To make the matrix denser","To remove missing values"],"c":0,"x":"Centring removes each user's personal rating scale."},"L27-2":{"n":27,"s":"quiz","st":"Check your understanding","q":"In matrix factorisation, a predicted rating is…","o":["The item's average","The nearest user's rating","The global mean plus user and item biases plus the dot product of their factor vectors"],"c":2,"x":"$\\hat{r}_{ui} = \\mu + b_u + b_i + \\mathbf{p}_u\\cdot\\mathbf{q}_i$."},"L27-3":{"n":27,"s":"quiz","st":"Check your understanding","q":"A brand-new film has no ratings. Which method can still recommend it?","o":["Item-item collaborative filtering","Content-based filtering using its genre and description","Matrix factorisation"],"c":1,"x":"Collaborative methods need interactions; content features solve cold start."},"L27-4":{"n":27,"s":"quiz","st":"Check your understanding","q":"Of the 10 films recommended to a user, 7 are relevant. What is precision@10?","o":["0.7","7","It depends on how many relevant films exist"],"c":0,"x":"Precision@k is relevant items in the top k divided by k. (Recall@k would depend on the total number relevant.)"},"L28-0":{"n":28,"s":"quiz","st":"Check your understanding","q":"A Beta(2, 8) prior is updated with 3 successes and 7 failures. The posterior is…","o":["Beta(5, 15)","Beta(3, 7)","Beta(10, 20)"],"c":0,"x":"Add successes to $a$ and failures to $b$: Beta($2 + 3$, $8 + 7$)."},"L28-1":{"n":28,"s":"quiz","st":"Check your understanding","q":"The posterior mean of Bayesian linear regression with a normal prior equals…","o":["Ordinary least squares","Ridge regression","Lasso"],"c":1,"x":"With $\\lambda = \\sigma^2/\\tau^2$. A Laplace prior would give lasso at the MAP."},"L28-2":{"n":28,"s":"quiz","st":"Check your understanding","q":"Far from all training data, a Gaussian process's predictive standard deviation…","o":["Shrinks to zero","Stays equal to the noise","Grows back towards the prior's"],"c":2,"x":"With no nearby data, the GP has only its prior to go on."},"L28-3":{"n":28,"s":"quiz","st":"Check your understanding","q":"Why does the Metropolis algorithm not need the normalising constant $p(D)$?","o":["It only uses ratios of posterior values, in which $p(D)$ cancels","It estimates $p(D)$ first","Because the prior is flat"],"c":0,"x":"Accepting with probability min(1, posterior ratio) needs the posterior only up to a constant."},"L28-4":{"n":28,"s":"quiz","st":"Check your understanding","q":"In Thompson sampling, how is the design for each visitor chosen?","o":["Always the one with the highest observed rate","Draw a plausible rate for each design from its posterior and pick the highest draw","At random, evenly"],"c":1,"x":"Random draws let uncertain designs be tried sometimes, while clearly good ones are chosen most of the time."},"L29-0":{"n":29,"s":"quiz","st":"Check your understanding","q":"Customers who use a premium feature churn less. Why can't you conclude the feature reduces churn?","o":["The sample is too small","Engaged customers may both use the feature and stay anyway (confounding)","Churn can't be measured"],"c":1,"x":"Engagement drives both; a randomised test or adjustment is needed."},"L29-1":{"n":29,"s":"quiz","st":"Check your understanding","q":"Why does randomisation give an unbiased effect estimate?","o":["It makes the groups alike on average in everything, measured or not","It increases the sample size","It removes noise"],"c":0,"x":"The coin can't be influenced by any confounder."},"L29-2":{"n":29,"s":"quiz","st":"Check your understanding","q":"A treated person had a propensity score of 0.2. Their inverse propensity weight is…","o":["0.2","1.25","5"],"c":2,"x":"$1/0.2 = 5$: they represent the many similar people who weren't treated."},"L29-3":{"n":29,"s":"quiz","st":"Check your understanding","q":"What does difference-in-differences assume?","o":["The treated group was chosen at random","Without treatment, both groups would have followed parallel trends","There's no seasonality"],"c":1,"x":"The control group's change stands in for what would have happened to the treated group."},"L29-4":{"n":29,"s":"quiz","st":"Check your understanding","q":"Why target a coupon by predicted uplift instead of predicted purchase probability?","o":["High-probability buyers may buy anyway; uplift finds people whose behaviour the coupon changes","Uplift models are more accurate","Probabilities can't be ranked"],"c":0,"x":"The goal is extra purchases caused by the coupon."},"L30-0":{"n":30,"s":"quiz","st":"Check your understanding","q":"Why save the whole pipeline rather than just the model?","o":["It's smaller","So the exact same preprocessing is applied in production","Models can't be saved alone"],"c":1,"x":"Re-implementing the preprocessing separately is a classic source of production bugs."},"L30-1":{"n":30,"s":"quiz","st":"Check your understanding","q":"A feature's PSI between training and live data is 0.4. What does that suggest?","o":["The model is accurate","No change","A major shift in that feature's distribution"],"c":2,"x":"Above about 0.25 is usually treated as a major shift."},"L30-2":{"n":30,"s":"quiz","st":"Check your understanding","q":"Inputs look the same as in training, but accuracy has dropped. This is most likely…","o":["Concept drift: the input–outcome relationship changed","Data drift","A schema error"],"c":0,"x":"Only outcomes reveal it, so monitor performance once labels arrive."},"L30-3":{"n":30,"s":"quiz","st":"Check your understanding","q":"\"Increasing debt should never lower the predicted risk\" is an example of…","o":["An invariance test","A directional test","A load test"],"c":1,"x":"It checks the prediction moves the expected way."},"L30-4":{"n":30,"s":"quiz","st":"Check your understanding","q":"In a shadow deployment, the new model…","o":["Replaces the old one immediately","Serves 5% of users","Scores live traffic, but its answers are only logged and compared"],"c":2,"x":"It's a safe way to check a model on real data before it affects anyone."},"L31-0":{"n":31,"s":"quiz","st":"Check your understanding","q":"What does the discount factor $\\gamma$ control?","o":["The learning rate","How much future rewards count compared with immediate ones","The chance of exploring"],"c":1,"x":"Low $\\gamma$ makes the agent short-sighted."},"L31-1":{"n":31,"s":"quiz","st":"Check your understanding","q":"Value iteration needs…","o":["The transition probabilities and rewards","Only experience","Labelled actions"],"c":0,"x":"It's model-based; Q-learning is the model-free alternative."},"L31-2":{"n":31,"s":"quiz","st":"Check your understanding","q":"In Q-learning, the term $r + \\gamma \\max_{a'} Q(s', a') - Q(s, a)$ is…","o":["The reward","The policy","The temporal-difference error"],"c":2,"x":"The estimate moves a fraction $\\alpha$ of the way to the target."},"L31-3":{"n":31,"s":"quiz","st":"Check your understanding","q":"Why does an RL agent need exploration?","o":["To speed up computation","It can only learn about actions it actually tries","To reduce the discount"],"c":1,"x":"Its data comes from its own behaviour."},"L31-4":{"n":31,"s":"quiz","st":"Check your understanding","q":"With a very large step cost, the agent jumps into the pit. This shows…","o":["The agent optimises exactly the reward given, which may not match what we intended","Q-learning is broken","The discount is too high"],"c":0,"x":"Reward design shapes behaviour; this is reward hacking in miniature."},"L32-0":{"n":32,"s":"quiz","st":"Check your understanding","q":"What is a pseudo-label?","o":["A label from a domain expert","A model's own confident prediction used as a training label","A missing label"],"c":1,"x":"Self-training adds them to the training set."},"L32-1":{"n":32,"s":"quiz","st":"Check your understanding","q":"Lowering the self-training threshold from 0.9 to 0.6 reduced accuracy. Why?","o":["Too few pseudo-labels","The model underfit","More wrong pseudo-labels were added, so the model learned its own mistakes"],"c":2,"x":"That's confirmation bias."},"L32-2":{"n":32,"s":"quiz","st":"Check your understanding","q":"Label spreading mainly relies on which assumption?","o":["Nearby points tend to share a label","Classes are balanced","Features are independent"],"c":0,"x":"Labels flow along a nearest-neighbour graph."},"L32-3":{"n":32,"s":"quiz","st":"Check your understanding","q":"Uncertainty sampling sends for labelling the examples…","o":["The model is most confident about","The model is least sure about","Chosen at random"],"c":1,"x":"Those near the boundary teach it most."},"L32-4":{"n":32,"s":"quiz","st":"Check your understanding","q":"How should a semi-supervised model be evaluated?","o":["On its pseudo-labels","On the training labels","On a separate, properly labelled test set"],"c":2,"x":"Pseudo-labels contain the model's own errors."},"L33-0":{"n":33,"s":"quiz","st":"Check your understanding","q":"A customer joined 5 months ago and is still subscribed. In survival analysis, their record is…","o":["Deleted","Right-censored at 5 months","A churn at 5 months"],"c":1,"x":"We know only that they survived at least 5 months."},"L33-1":{"n":33,"s":"quiz","st":"Check your understanding","q":"At a churn time, 40 customers are at risk and 4 churn. By what factor does the Kaplan–Meier curve drop?","o":["0.9","0.1","0.96"],"c":0,"x":"$1 - 4/40 = 0.9$."},"L33-2":{"n":33,"s":"quiz","st":"Check your understanding","q":"A Cox coefficient of 0.4 for \"missed payments\" means…","o":["40% churn","Churn 0.4 months earlier","Each missed payment multiplies the churn hazard by $e^{0.4} \\approx 1.49$"],"c":2,"x":"The hazard ratio is $e^\\beta$."},"L33-3":{"n":33,"s":"quiz","st":"Check your understanding","q":"Why is the median survival time usually reported instead of the mean?","o":["It's always larger","The mean depends on the long tail, which censoring often hides","Means can't be computed for times"],"c":1,"x":"The median only needs the curve to cross 0.5."},"L33-4":{"n":33,"s":"quiz","st":"Check your understanding","q":"A survival model has a concordance index of 0.5. That means…","o":["It orders who churns first no better than random","It's 50% accurate","Half the customers are censored"],"c":0,"x":"0.5 is random ordering; 1 is perfect."},"L34-0":{"n":34,"s":"quiz","st":"Check your understanding","q":"In PageRank, a node is important if…","o":["It has a long name","Important nodes link to it","It links to many nodes"],"c":1,"x":"Importance flows along incoming links."},"L34-1":{"n":34,"s":"quiz","st":"Check your understanding","q":"What does a modularity near 0 mean for a grouping?","o":["No more edges inside groups than random wiring would give","Perfect communities","The graph has no edges"],"c":0,"x":"Clear community structure gives values above about 0.3."},"L34-2":{"n":34,"s":"quiz","st":"Check your understanding","q":"Why does Adamic–Adar down-weight shared neighbours with high degree?","o":["They're less reliable data","To speed it up","A shared celebrity says less about two people than a shared friend with few friends"],"c":2,"x":"Rare shared neighbours carry more information."},"L34-3":{"n":34,"s":"quiz","st":"Check your understanding","q":"Adding contacts' average signal improved accuracy because of…","o":["Overfitting","Homophily: connected nodes tend to be similar","A larger dataset"],"c":1,"x":"Neighbours' information averages out each node's noise."},"L34-4":{"n":34,"s":"quiz","st":"Check your understanding","q":"Why must train/test splits be careful with graph features?","o":["Connected nodes can leak label information to each other","Graphs can't be split","PageRank changes randomly"],"c":0,"x":"Use only information that would be known at prediction time."},"L35-0":{"n":35,"s":"quiz","st":"Check your understanding","q":"In a Bayesian network, each node needs a probability table for…","o":["Every other variable","Its value given its parents","Its children"],"c":1,"x":"The joint is the product of these local tables."},"L35-1":{"n":35,"s":"quiz","st":"Check your understanding","q":"Wet grass raises the chance of rain, but learning the sprinkler was on lowers it again. This is…","o":["Overfitting","Confounding","Explaining away"],"c":2,"x":"One cause explains the effect, so the other becomes less likely."},"L35-2":{"n":35,"s":"quiz","st":"Check your understanding","q":"What does the Viterbi algorithm find?","o":["The single most likely sequence of hidden states","The probability of the observations","The transition matrix"],"c":0,"x":"The forward algorithm gives the probability; Viterbi the best path."},"L35-3":{"n":35,"s":"quiz","st":"Check your understanding","q":"An HMM's transition matrix entry $T_{ij}$ is…","o":["P(observation j | state i)","P(next state j | current state i)","P(state i and j together)"],"c":1,"x":"Emissions are the observation probabilities."},"L35-4":{"n":35,"s":"quiz","st":"Check your understanding","q":"How are HMM parameters learned when hidden states aren't labelled?","o":["They can't be","By counting","With Baum–Welch (expectation–maximisation)"],"c":2,"x":"It alternates between estimating states and re-estimating parameters."},"P1-0":{"n":1,"s":"types","st":"The main types of machine learning","q":"A shop wants to group its customers into segments with similar habits. It has no labels saying which segment anyone belongs to. What kind of learning is this?","o":["Supervised classification","Unsupervised learning (clustering)","Reinforcement learning"],"c":1,"x":"There are no labels to learn from, so the goal is to discover structure: clustering, a type of unsupervised learning."},"P1-1":{"n":1,"s":"vocabulary","st":"The essential vocabulary","q":"A model predicts a house's price from its area and age. In this dataset, the price column is the…","o":["feature","label (target)","parameter"],"c":1,"x":"The label is what we want to predict. Area and age are features; the parameters are the numbers the model learns."},"P1-2":{"n":1,"s":"how-learning-works","st":"How does a model actually \"learn\"?","q":"What does \"training\" a model mean?","o":["Writing its rules by hand","Adjusting its parameters to reduce the loss on the training examples","Storing the test set inside the model"],"c":1,"x":"Training searches for parameter values that make the loss (the error on the examples) as small as possible."},"P1-3":{"n":1,"s":"workflow","st":"The machine learning workflow","q":"Why is the test set kept aside until the very end?","o":["It makes training faster","It gives an honest estimate of performance on data the model has never seen","Libraries refuse to train on it"],"c":1,"x":"If the test set influences any choice, its score becomes optimistic. Used only once at the end, it estimates real-world performance."},"P1-4":{"n":2,"s":"dot-product","st":"The dot product — the most important operation in ML","q":"What is $(2, -1)\\cdot(3, 4)$?","o":["$2$","$10$","$(6, -4)$"],"c":0,"x":"$2\\times3 + (-1)\\times4 = 6 - 4 = 2$. A dot product is a single number, not a vector."},"P1-5":{"n":2,"s":"length","st":"Length (norm) and distance","q":"What is the length of the vector $(6, 8)$?","o":["$14$","$10$","$100$"],"c":1,"x":"$\\sqrt{6^2 + 8^2} = \\sqrt{100} = 10$."},"P1-6":{"n":2,"s":"matmul","st":"Matrix × matrix","q":"$A$ is $4\\times3$ and $B$ is $3\\times5$. What is the shape of $AB$?","o":["$3\\times3$","$4\\times5$","They can't be multiplied"],"c":1,"x":"The inner sizes (3 and 3) match, and the result takes the outer sizes: $4\\times5$."},"P1-7":{"n":2,"s":"dot-product","st":"The dot product — the most important operation in ML","q":"Two non-zero vectors have a dot product of 0. They are…","o":["parallel","perpendicular","identical"],"c":1,"x":"A dot product of zero means $\\cos\\theta = 0$, so the angle between them is 90°."},"P1-8":{"n":3,"s":"rules","st":"The rules you actually need","q":"For $f(x) = x^3$, what is $f'(2)$?","o":["$6$","$8$","$12$"],"c":2,"x":"The power rule gives $f'(x) = 3x^2$, and $3\\times2^2 = 12$."},"P1-9":{"n":3,"s":"chain-rule","st":"The chain rule — the engine of deep learning","q":"What is the derivative of $e^{2x}$?","o":["$e^{2x}$","$2e^{2x}$","$2x\\,e^{2x-1}$"],"c":1,"x":"Chain rule: the outer derivative $e^{u}$ times the inner derivative $2$."},"P1-10":{"n":3,"s":"gradient","st":"The gradient: the direction of steepest ascent","q":"The gradient of a function points in the direction of…","o":["steepest increase","steepest decrease","zero slope"],"c":0,"x":"The gradient points uphill. That's why gradient descent steps in the opposite direction, $-\\nabla L$."},"P1-11":{"n":3,"s":"partial","st":"Partial derivatives: more than one parameter","q":"For $f(w, b) = 3w + b^2$, what is $\\partial f/\\partial b$ at $(w, b) = (1, 2)$?","o":["$3$","$4$","$7$"],"c":1,"x":"Treat $w$ as a constant: $\\partial f/\\partial b = 2b = 4$."},"P1-12":{"n":4,"s":"conditional","st":"Conditional probability","q":"$P(A) = 0.3$ and $P(B \\mid A) = 0.5$. What is $P(A \\text{ and } B)$?","o":["$0.8$","$0.15$","$0.6$"],"c":1,"x":"$P(A \\text{ and } B) = P(B\\mid A)\\,P(A) = 0.5\\times0.3 = 0.15$."},"P1-13":{"n":4,"s":"describing-data","st":"Describing data: mean, variance, standard deviation","q":"For the data $1, 2, 3, 4, 10$, which summary is pulled most by the value 10?","o":["The mean","The median","Both equally"],"c":0,"x":"The mean is 4 but the median is 3. Change 10 to 100 and the mean jumps to 22 while the median stays at 3."},"P1-14":{"n":4,"s":"distributions","st":"Probability distributions","q":"About what share of a normal distribution lies within one standard deviation of the mean?","o":["50%","68%","95%"],"c":1,"x":"Roughly 68% lies within $\\pm1\\sigma$, 95% within $\\pm2\\sigma$ and 99.7% within $\\pm3\\sigma$."},"P2-0":{"n":5,"s":"underfit-overfit","st":"Underfitting, good fit and overfitting","q":"Training accuracy is 99% but validation accuracy is 70%. What's the most likely problem?","o":["Underfitting","Overfitting","A perfect fit"],"c":1,"x":"A large gap between training and validation performance is the signature of overfitting: the model memorised the training data."},"P2-1":{"n":5,"s":"cross-validation","st":"k-fold cross-validation","q":"In 5-fold cross-validation, how many times is each example used for validation?","o":["Once","Five times","Never"],"c":0,"x":"The data is split into 5 folds; each fold is the validation set exactly once, so each example is validated once."},"P2-2":{"n":5,"s":"leakage","st":"Data leakage: the silent killer","q":"A team standardises the whole dataset, then splits it into training and test sets. What's the problem?","o":["Nothing — scaling is harmless","Data leakage: test-set statistics influenced the training data","The model will underfit"],"c":1,"x":"The scaler saw the test rows. Fit preprocessing on the training data only, ideally inside a pipeline."},"P2-3":{"n":6,"s":"model","st":"The model","q":"A model is $\\hat{y} = 3 + 2x$. What does it predict for $x = 4$?","o":["$11$","$20$","$9$"],"c":0,"x":"$3 + 2\\times4 = 11$."},"P2-4":{"n":6,"s":"r2","st":"How good is the fit? R²","q":"A regression model has $R^2 = 0$ on test data. This means it…","o":["predicts perfectly","is no better than always predicting the average","is always wrong by exactly zero"],"c":1,"x":"$R^2 = 1 - \\text{SS}_{res}/\\text{SS}_{tot}$. When it's 0, the model's error equals that of predicting the mean."},"P2-5":{"n":6,"s":"interpret","st":"Interpreting the weights","q":"In a multiple regression for price, the weight on age is $-1.2$. This means…","o":["each extra year lowers the predicted price by 1.2, holding the other features fixed","age causes prices to fall","age is the least important feature"],"c":0,"x":"A weight is the change in prediction per unit of that feature with the others held constant. It shows association, not causation."},"P2-6":{"n":7,"s":"learning-rate","st":"Choosing the learning rate","q":"During gradient descent, the loss gets bigger and bigger at each step. What's the most likely cause?","o":["The learning rate is too small","The learning rate is too large","There are too many features"],"c":1,"x":"Too large a step overshoots the minimum, each time by more — the loss diverges."},"P2-7":{"n":7,"s":"algorithm","st":"The algorithm, step by step","q":"$L(w) = w^2$, $w = 3$, learning rate $0.1$. What is $w$ after one step?","o":["$2.4$","$2.7$","$0$"],"c":0,"x":"$L'(3) = 6$, so $w = 3 - 0.1\\times6 = 2.4$."},"P2-8":{"n":7,"s":"scaling","st":"Why feature scaling matters","q":"Why does gradient descent benefit from feature scaling?","o":["It makes the model more accurate at the optimum","Features on very different scales make the loss surface long and narrow, so steps zig-zag slowly","It removes outliers"],"c":1,"x":"With scaled features the contours are rounder, so one learning rate works well for every weight."},"P2-9":{"n":8,"s":"sigmoid","st":"The sigmoid function","q":"For what value of $z$ is $\\sigma(z) = 0.5$?","o":["$z = 0$","$z = 0.5$","$z = 1$"],"c":0,"x":"$\\sigma(0) = 1/(1 + e^0) = 1/2$. That's why the decision boundary is where $z = 0$."},"P2-10":{"n":8,"s":"loss","st":"The loss: log loss (cross-entropy)","q":"Logistic regression is trained by minimising…","o":["mean squared error","log loss (cross-entropy)","the number of misclassified points"],"c":1,"x":"Log loss is convex for logistic regression and heavily punishes confident wrong predictions."},"P2-11":{"n":9,"s":"metrics","st":"Accuracy, precision, recall, specificity","q":"100 patients, 5 of them sick. A model predicts \"healthy\" for everyone. What are its accuracy and recall?","o":["95% accuracy, recall 0","5% accuracy, recall 1","95% accuracy, recall 1"],"c":0,"x":"It's right for the 95 healthy patients (accuracy 95%) but finds none of the 5 sick ones (recall 0). Accuracy hides this on imbalanced data."},"P2-12":{"n":9,"s":"threshold","st":"The threshold trade-off","q":"You raise a classifier's threshold from 0.5 to 0.8. What usually happens?","o":["Precision goes up, recall goes down","Precision goes down, recall goes up","Both go up"],"c":0,"x":"Fewer, more confident positives: fewer false alarms (higher precision) but more misses (lower recall)."},"P2-13":{"n":10,"s":"bias-variance","st":"Bias and variance","q":"A straight line fitted to clearly curved data is an example of…","o":["high variance","high bias","data leakage"],"c":1,"x":"The model is too simple to capture the pattern — high bias, underfitting."},"P2-14":{"n":10,"s":"ridge","st":"Ridge regression (L2)","q":"What happens as you increase $\\lambda$ in ridge regression?","o":["The weights shrink towards zero and training error rises","The weights grow and training error falls","Nothing changes"],"c":0,"x":"A stronger penalty trades a little training error for smaller, more stable weights — less variance."},"P3-0":{"n":11,"s":"algorithm","st":"The algorithm","q":"What does kNN do during \"training\"?","o":["Learns a weight for each feature","Simply stores the training data","Builds a tree of questions"],"c":1,"x":"kNN is a lazy learner: all the work happens at prediction time, when distances are computed."},"P3-1":{"n":11,"s":"choosing-k","st":"Choosing k: bias vs variance again","q":"Compared with $k = 25$, a kNN model with $k = 1$ has…","o":["lower variance","higher variance (more likely to overfit)","the same behaviour"],"c":1,"x":"With $k = 1$ every training point decides its own small region, including noisy points — low bias, high variance."},"P3-2":{"n":11,"s":"scaling","st":"Feature scaling is essential","q":"Why must features usually be scaled before kNN?","o":["Distances would be dominated by the features with the largest numbers","kNN only accepts values between 0 and 1","Scaling makes kNN train faster"],"c":0,"x":"A salary difference of thousands would swamp an age difference of a few years."},"P3-3":{"n":11,"s":"distance","st":"Measuring distance","q":"What is the Manhattan distance between $(0, 0)$ and $(3, -4)$?","o":["$5$","$7$","$1$"],"c":1,"x":"$|3| + |-4| = 7$. (The Euclidean distance would be 5.)"},"P3-4":{"n":12,"s":"naive","st":"The \"naive\" assumption","q":"What is the \"naive\" assumption in Naive Bayes?","o":["All classes are equally likely","Features are independent of each other given the class","The data is normally distributed"],"c":1,"x":"It lets the likelihood factor into a product of one-feature terms, which makes the model fast and data-efficient."},"P3-5":{"n":12,"s":"logs","st":"Working with logs","q":"Why do Naive Bayes implementations add log-probabilities instead of multiplying probabilities?","o":["Logs are more accurate in theory","Multiplying many tiny numbers underflows to zero on a computer","Logs make the classes balanced"],"c":1,"x":"The log turns a product into a sum and keeps the numbers in a range computers can store; the winning class doesn't change."},"P3-6":{"n":12,"s":"spam-example","st":"Worked example: a spam filter by hand","q":"Why is add-one (Laplace) smoothing used?","o":["A word never seen in a class would get probability 0 and veto that class completely","To make training faster","To remove common words"],"c":0,"x":"Without smoothing, one unseen word multiplies the whole class score by zero."},"P3-7":{"n":13,"s":"impurity","st":"How does a tree choose its questions? Impurity","q":"What is the Gini impurity of a node where every example has the same class?","o":["$0$","$0.5$","$1$"],"c":0,"x":"$1 - 1^2 = 0$: a pure node has no impurity."},"P3-8":{"n":13,"s":"split","st":"Scoring a split: information gain","q":"How does a decision tree choose each split?","o":["At random","It picks the split that reduces impurity the most (largest information gain)","It always splits the first feature at its median"],"c":1,"x":"CART tries the candidate thresholds for every feature and keeps the best one."},"P3-9":{"n":13,"s":"overfitting","st":"Trees overfit easily — and how to stop them","q":"A decision tree grown with no depth limit usually…","o":["underfits","memorises the training data and overfits","becomes a linear model"],"c":1,"x":"It keeps splitting until the leaves are pure, fitting noise. Limit max_depth or min_samples_leaf, or prune."},"P3-10":{"n":14,"s":"random-forest","st":"Random forests","q":"What does a random forest add on top of bagging?","o":["Each split considers only a random subset of the features","Trees are trained one after another","Each tree sees the whole dataset"],"c":0,"x":"Random feature subsets make the trees more different from one another, so averaging them helps more."},"P3-11":{"n":14,"s":"gradient-boosting","st":"Gradient boosting","q":"In gradient boosting, each new tree is trained to predict…","o":["the original labels","the residuals (remaining errors) of the current model","a random subset of the labels"],"c":1,"x":"Each tree corrects what the ensemble still gets wrong; its prediction is added with a learning rate."},"P3-12":{"n":14,"s":"why-it-works","st":"Why combining models works: the maths","q":"Averaging many models helps most when their errors are…","o":["identical","uncorrelated","all very large"],"c":1,"x":"If the models make the same mistakes, averaging can't cancel them. Independent errors cancel out."},"P3-13":{"n":15,"s":"margin","st":"The margin","q":"In an SVM, the support vectors are…","o":["all the training points","the points on or inside the margin, which define the boundary","the points furthest from the boundary"],"c":1,"x":"Only these points affect the solution; the others could be removed without changing the boundary."},"P3-14":{"n":15,"s":"soft-margin","st":"Soft margins and the hinge loss","q":"What happens when you make $C$ very large in a soft-margin SVM?","o":["More margin violations are allowed and the margin widens","Fewer violations are allowed, the margin narrows and the risk of overfitting grows","$C$ has no effect"],"c":1,"x":"A large $C$ punishes violations heavily, so the SVM bends to fit every training point."},"P4-0":{"n":16,"s":"idea","st":"Learning without labels","q":"How does clustering differ from classification?","o":["Clustering has no labels; it discovers groups by itself","Clustering needs more labels","There is no difference"],"c":0,"x":"Classification learns from labelled examples; clustering finds structure without any labels."},"P4-1":{"n":16,"s":"kmeans","st":"k-means: the classic algorithm","q":"In the assign step of k-means, each point…","o":["moves towards the centre of the data","joins the cluster of its nearest centroid","joins a random cluster"],"c":1,"x":"Assign: nearest centroid. Update: move each centroid to the mean of its points."},"P4-2":{"n":16,"s":"kmeans","st":"k-means: the classic algorithm","q":"In the update step, each centroid moves to…","o":["the point furthest from it","the mean of the points assigned to it","the origin"],"c":1,"x":"The mean minimises the sum of squared distances to the cluster's points."},"P4-3":{"n":16,"s":"kmeans","st":"k-means: the classic algorithm","q":"1D points $2, 4, 10, 12$ with starting centroids $2$ and $12$. Where are the centroids after one assign + update step?","o":["$3$ and $11$","$2$ and $12$","$4$ and $10$"],"c":0,"x":"Assign: $\\{2, 4\\}$ and $\\{10, 12\\}$. Means: $3$ and $11$."},"P4-4":{"n":16,"s":"init","st":"Initialisation matters: k-means++","q":"What does k-means++ change?","o":["It chooses starting centroids spread far apart","It removes the need to choose $k$","It allows non-round clusters"],"c":0,"x":"Spread-out starts avoid poor local solutions, such as two centroids in the same blob."},"P4-5":{"n":16,"s":"choosing-k","st":"Choosing k","q":"The elbow method plots…","o":["accuracy against $k$","inertia against $k$","the number of points per cluster"],"c":1,"x":"Inertia always falls as $k$ grows; the \"elbow\" is where the big drops stop."},"P4-6":{"n":16,"s":"limits","st":"Limitations of k-means","q":"k-means works poorly when clusters…","o":["are round and of similar size","are long, curved or of very different sizes","are far apart"],"c":1,"x":"k-means assumes compact, roughly spherical clusters around centroids."},"P4-7":{"n":16,"s":"dbscan","st":"DBSCAN: clusters as dense regions","q":"In DBSCAN, a point with too few neighbours that is not within eps of any core point is labelled…","o":["a core point","a border point","noise"],"c":2,"x":"Noise points belong to no cluster — useful for spotting outliers."},"P4-8":{"n":16,"s":"evaluating","st":"How do you know a clustering is good?","q":"A point's silhouette value is close to 1. This means it is…","o":["on the border between two clusters","well inside its own cluster and far from the others","probably in the wrong cluster"],"c":1,"x":"$s = (b - a)/\\max(a, b)$ is near 1 when $a$ (own cluster) is much smaller than $b$ (nearest other cluster)."},"P4-9":{"n":16,"s":"hierarchical","st":"Hierarchical clustering","q":"Cutting a dendrogram at a lower height gives…","o":["fewer clusters","more clusters","the same clusters"],"c":1,"x":"Lower cuts happen before many merges, so more separate groups remain."},"P4-10":{"n":17,"s":"variance-idea","st":"The key idea: keep the directions with the most variance","q":"The first principal component is the direction in which the data has…","o":["the most variance","the least variance","the most outliers"],"c":0,"x":"PCA keeps the directions of greatest spread, because they carry the most information."},"P4-11":{"n":17,"s":"algorithm","st":"PCA step by step","q":"Your features are a person's height in metres and income in rupees. What should you do before PCA?","o":["Nothing","Standardise the features","Sort the rows"],"c":1,"x":"Otherwise income, with its huge numbers, dominates the variance and PC1 is just \"income\"."},"P4-12":{"n":17,"s":"choosing-k","st":"How many components?","q":"Eigenvalues are $6, 3, 1$. What share of the variance does PC1 explain?","o":["$60\\%$","$50\\%$","$90\\%$"],"c":0,"x":"$6/(6 + 3 + 1) = 0.6$."},"P4-13":{"n":17,"s":"eigen","st":"Eigenvectors: the directions PCA finds","q":"The principal components are always…","o":["parallel to the original axes","perpendicular (orthogonal) to each other","of equal length"],"c":1,"x":"Eigenvectors of a symmetric covariance matrix are orthogonal, so each component captures new, uncorrelated variation."},"P4-14":{"n":17,"s":"tsne","st":"Beyond PCA: t-SNE and UMAP for visualisation","q":"What is t-SNE mainly used for?","o":["Visualising high-dimensional data in 2D","Producing features for a model","Speeding up linear regression"],"c":0,"x":"t-SNE preserves neighbourhoods for pictures; its axes and between-cluster distances have no meaning."},"P5-0":{"n":18,"s":"neuron","st":"The artificial neuron","q":"A ReLU neuron has weights $(1, 2)$ and bias $-1$. What does it output for input $(1, 1)$?","o":["$0$","$2$","$3$"],"c":1,"x":"$z = 1 + 2 - 1 = 2$, and $\\text{ReLU}(2) = 2$."},"P5-1":{"n":18,"s":"xor","st":"Why one neuron isn't enough: XOR","q":"Why can't a single neuron learn XOR?","o":["XOR needs too much data","XOR is not linearly separable — no single straight line separates the classes","Neurons can't output 0"],"c":1,"x":"One neuron draws one line. XOR needs at least two, which a hidden layer provides."},"P5-2":{"n":18,"s":"activations","st":"Activation functions","q":"What happens if a deep network uses no non-linear activation functions?","o":["It becomes more powerful","All the layers collapse into one linear model","It can't be trained at all"],"c":1,"x":"A composition of linear maps is still linear, so depth adds nothing without non-linearities."},"P5-3":{"n":18,"s":"backprop","st":"Backpropagation: the chain rule, backwards","q":"What does backpropagation compute?","o":["The predictions for the test set","The gradient of the loss with respect to every weight, using the chain rule","The best learning rate"],"c":1,"x":"It passes error signals backwards layer by layer; gradient descent then uses those gradients to update the weights."},"P5-4":{"n":18,"s":"architecture","st":"Layers: the multilayer perceptron","q":"How many parameters does a dense layer with 3 inputs and 4 neurons have?","o":["$12$","$16$","$7$"],"c":1,"x":"$3\\times4$ weights plus 4 biases $= 16$."},"P5-5":{"n":19,"s":"training","st":"Making deep networks trainable","q":"Why do deep networks with sigmoid activations train slowly in their early layers?","o":["Vanishing gradients: the sigmoid's derivative is at most 0.25, so gradients shrink layer by layer","Sigmoids are too slow to compute","They have too few parameters"],"c":0,"x":"ReLU, careful initialisation, normalisation and skip connections fix this."},"P5-6":{"n":19,"s":"cnn","st":"Convolutional neural networks (CNNs)","q":"Why are convolutional networks well suited to images?","o":["They share small filters across the whole image, detecting local patterns with far fewer parameters","They ignore pixel positions completely","They need no training"],"c":0,"x":"The same edge detector works anywhere in the image, so weights are reused instead of learned per pixel."},"P5-7":{"n":19,"s":"cnn","st":"Convolutional neural networks (CNNs)","q":"A $3\\times3$ kernel slides over a $10\\times10$ image with no padding and stride 1. How wide is the output?","o":["$10$","$8$","$7$"],"c":1,"x":"$(10 - 3)/1 + 1 = 8$."},"P5-8":{"n":19,"s":"transformers","st":"Transformers and attention","q":"What does attention let each token in a Transformer do?","o":["Look only at the previous token","Weigh every other token by how relevant it is","Ignore word order entirely"],"c":1,"x":"Attention scores (softmax of query–key dot products) decide how much each token draws from the others."},"P5-9":{"n":19,"s":"transfer","st":"Transfer learning: standing on giants' shoulders","q":"What is transfer learning?","o":["Starting from a model pretrained on a large dataset and fine-tuning it for your task","Moving a model to another computer","Training two models at once"],"c":0,"x":"Pretrained features need far less data and compute than training from scratch."},"P5-10":{"n":19,"s":"training","st":"Making deep networks trainable","q":"What does dropout do during training?","o":["Removes training examples","Randomly switches off neurons so the network can't rely on any single one","Lowers the learning rate"],"c":1,"x":"It's a regulariser: it reduces overfitting. At prediction time all neurons are used."},"P5-11":{"n":20,"s":"categorical","st":"Categorical features","q":"Why one-hot encode \"colour\" (red, green, blue) instead of coding it as 1, 2, 3?","o":["Numbers 1, 2, 3 imply an order and spacing that colours don't have","One-hot uses less memory","Models can't read numbers"],"c":0,"x":"With 1, 2, 3 a linear model would assume blue = 3 × red. One-hot gives each colour its own column."},"P5-12":{"n":20,"s":"missing","st":"Missing values","q":"You fill missing ages with the median. The median should be computed from…","o":["the whole dataset","the training data only","the test data only"],"c":1,"x":"Using test rows would leak information. A pipeline does this automatically."},"P5-13":{"n":20,"s":"pipelines","st":"Pipelines: preprocessing done right","q":"What is the main benefit of putting preprocessing inside a Pipeline when cross-validating?","o":["It re-fits the preprocessing inside each fold, so there's no leakage","It makes the model more complex","It removes the need for a test set"],"c":0,"x":"And the same fitted steps travel with the model into production."},"P5-14":{"n":20,"s":"production","st":"After deployment: monitoring","q":"A model's accuracy slowly drops months after deployment because the incoming data has changed. This is called…","o":["overfitting","distribution shift","underfitting"],"c":1,"x":"The world changed (Lesson 5). Monitor inputs and predictions, and retrain on recent data."},"P6-0":{"n":22,"s":"joins","st":"Joins: combining tables","q":"You LEFT JOIN customers to their orders and then sum a customer-level column. The total is too high. Why?","o":["LEFT JOIN drops rows","Each customer row is repeated once per order, so the sum counts customers many times","SQL can't sum"],"c":1,"x":"Aggregate the many side to one row per key before joining, and check row counts after every join."},"P6-1":{"n":22,"s":"pit","st":"Point-in-time correctness: the rule that prevents leakage","q":"Features for a churn model are built from events. Which rule prevents leakage?","o":["Use all events in the table","Only use events strictly before each row's prediction time","Shuffle the rows first"],"c":1,"x":"Put the time condition in the join, and split train and test by time too."},"P6-2":{"n":23,"s":"random","st":"Random search","q":"Only 2 of 6 hyperparameters really matter. Why does random search tend to beat a grid with the same budget?","o":["It tests many more distinct values of the important hyperparameters","It always finds the optimum","It uses no validation"],"c":0,"x":"A grid repeats the same few values of each dimension; random trials try new ones every time."},"P6-3":{"n":23,"s":"nested","st":"Reporting honestly: nested cross-validation","q":"Why is the best cross-validation score from a big search an optimistic estimate?","o":["It's the maximum over many noisy estimates on the same folds","Cross-validation is always wrong","Because of the learning rate"],"c":0,"x":"Nested cross-validation or an untouched test set gives an honest estimate."},"P6-4":{"n":24,"s":"permutation","st":"Permutation importance","q":"Permutation importance measures…","o":["How often a feature is used in splits","How much a held-out score drops when the feature's values are shuffled","The feature's correlation with the target"],"c":1,"x":"It is model-agnostic and computed on held-out data."},"P6-5":{"n":24,"s":"shap","st":"SHAP values: fair credit for each feature","q":"SHAP values for one prediction always add up to…","o":["1","The prediction minus the baseline (average) prediction","The number of features"],"c":1,"x":"That's the efficiency property of Shapley values."},"P6-6":{"n":25,"s":"metrics","st":"Why accuracy fails, in numbers","q":"With 0.5% fraud, which metric is most useful for comparing detectors?","o":["Accuracy","Average precision (area under the precision–recall curve)","Training loss"],"c":1,"x":"Accuracy is dominated by the majority class; compare average precision with its baseline, the fraud rate."},"P6-7":{"n":25,"s":"anomaly","st":"Anomaly detection without labels","q":"Why does Isolation Forest give anomalies high scores?","o":["They are separated by random splits after very few steps","They have the most neighbours","They are labelled"],"c":0,"x":"Short average path length means easy to isolate."},"P6-8":{"n":26,"s":"validation","st":"Validating forecasts: backtesting","q":"Which validation is right for a daily sales forecast?","o":["Shuffled 5-fold cross-validation","Time-ordered backtesting: train up to a date, test on the next block, repeat","Testing on the training data"],"c":1,"x":"Validation must never train on the future."},"P6-9":{"n":26,"s":"features","st":"Turning a series into features","q":"A model's MASE is 0.8. What does that mean?","o":["Its error is 20% lower than the seasonal naive forecast's","It's 80% accurate","It's worse than the baseline"],"c":0,"x":"MASE divides the model's MAE by the seasonal naive MAE; below 1 beats the baseline."},"P6-10":{"n":27,"s":"evaluation","st":"Evaluating recommendations: rankings, not ratings","q":"Why evaluate a recommender with precision@k rather than only RMSE?","o":["Users see a short ranked list, so the top few items matter most","RMSE can't be computed","Precision is always higher"],"c":0,"x":"Ranking metrics on held-out interactions match what users experience."},"P6-11":{"n":27,"s":"practice","st":"Cold start, content and feedback loops","q":"A brand-new item has no interactions. Which approach can still recommend it?","o":["Item–item collaborative filtering","Content-based similarity using its features","Matrix factorisation alone"],"c":1,"x":"That's the cold-start problem; content features bridge it."},"P6-12":{"n":28,"s":"ab","st":"A Bayesian A/B test","q":"A Beta(1, 1) prior is updated with 40 conversions from 400 visitors. The posterior is…","o":["Beta(41, 361)","Beta(40, 400)","Beta(41, 401)"],"c":0,"x":"Add conversions to a and non-conversions (360) to b."},"P6-13":{"n":28,"s":"gp","st":"Gaussian processes","q":"Far from all training points, a Gaussian process's predictive uncertainty…","o":["drops to zero","grows back towards the prior's","equals the training error"],"c":1,"x":"With no nearby data, only the prior is left."},"P6-14":{"n":28,"s":"decide","st":"Deciding under uncertainty: Thompson sampling","q":"What does Thompson sampling do for each visitor?","o":["Shows designs in turn","Samples a plausible rate for each design from its posterior and shows the highest","Always shows the best observed design"],"c":1,"x":"This balances exploring uncertain designs with exploiting good ones."},"P7-0":{"n":29,"s":"potential","st":"Potential outcomes","q":"Discount-takers spend 30 more, but loyal customers were more likely to get discounts. The 30 is…","o":["The causal effect of the discount","Possibly mostly confounding by loyalty","Always an underestimate"],"c":1,"x":"Loyalty drives both; randomise or adjust."},"P7-1":{"n":29,"s":"did","st":"Difference-in-differences","q":"Treated region: +60 after a change; comparable untreated region: +40 over the same period. The difference-in-differences estimate is…","o":["100","60","20"],"c":2,"x":"60 − 40, assuming parallel trends."},"P7-2":{"n":29,"s":"uplift","st":"Who benefits? Uplift modelling","q":"Why target an offer by predicted uplift rather than predicted purchase?","o":["Some likely buyers would buy anyway","Uplift is easier to compute","Purchase can't be predicted"],"c":0,"x":"Uplift finds people whose behaviour changes."},"P7-3":{"n":30,"s":"drift","st":"Detecting data drift","q":"A feature's PSI between training and live data is 0.35. This indicates…","o":["No change","A major distribution shift","Higher accuracy"],"c":1,"x":"Above about 0.25 is a major shift."},"P7-4":{"n":30,"s":"monitor","st":"Concept drift and retraining","q":"Inputs look unchanged, but accuracy has dropped. Most likely…","o":["Concept drift","Data drift","A schema error"],"c":0,"x":"The input–outcome relationship changed."},"P7-5":{"n":30,"s":"testing","st":"Testing ML code","q":"\"Raising income must not raise predicted risk\" is…","o":["An invariance test","A directional test","A load test"],"c":1,"x":"It checks the direction of change."},"P7-6":{"n":31,"s":"bellman","st":"Values and the Bellman equation","q":"Value iteration repeatedly applies…","o":["Gradient descent","The Bellman equation to every state","Random search"],"c":1,"x":"Until the values stop changing."},"P7-7":{"n":31,"s":"qlearning","st":"Learning without a model: Q-learning","q":"Q-learning needs…","o":["The transition probabilities","Only experience: states, actions, rewards and next states","Labelled correct actions"],"c":1,"x":"It's model-free."},"P7-8":{"n":32,"s":"self","st":"Self-training with pseudo-labels","q":"Lowering a self-training confidence threshold too far tends to…","o":["Add many wrong pseudo-labels and hurt accuracy","Always improve accuracy","Reduce the training set"],"c":0,"x":"The model learns its own mistakes."},"P7-9":{"n":32,"s":"active","st":"Active learning: choose what to label","q":"Uncertainty sampling asks a person to label…","o":["Examples the model is most confident about","Examples the model is least sure about","Random examples"],"c":1,"x":"Those near the decision boundary."},"P7-10":{"n":33,"s":"km","st":"The Kaplan–Meier estimator","q":"At an event time, 50 customers are at risk and 5 churn. The Kaplan–Meier curve is multiplied by…","o":["0.9","0.1","0.95"],"c":0,"x":"1 − 5/50."},"P7-11":{"n":33,"s":"cox","st":"The Cox proportional hazards model","q":"A Cox coefficient of 0.69 gives a hazard ratio of about…","o":["0.69","2","0.5"],"c":1,"x":"e^0.69 ≈ 2."},"P7-12":{"n":34,"s":"centrality","st":"Who matters? Centrality","q":"In PageRank, a link counts more when it comes from…","o":["A node with many outgoing links","An important node","A new node"],"c":1,"x":"Importance flows along links."},"P7-13":{"n":34,"s":"links","st":"Predicting missing links","q":"Common-neighbour scores predict links well when…","o":["Friends of friends tend to connect","Connections are random","The graph has no triangles"],"c":0,"x":"That's the mechanism they assume."},"P7-14":{"n":35,"s":"viterbi","st":"Decoding: the Viterbi algorithm","q":"The Viterbi algorithm returns…","o":["The probability of the observations","The most likely sequence of hidden states","The emission matrix"],"c":1,"x":"The forward algorithm gives the probability."}};